def trap(height):
    if not height or len(height) < 3:
        return 0

    # Calculate max height to the left of each position (including current)
    left_max = []
    current_max = 0
    for h in height:
        current_max = max(current_max, h)
        left_max.append(current_max)

    # Calculate max height to the right of each position (including current)
    right_max = []
    current_max = 0
    for h in reversed(height):
        current_max = max(current_max, h)
        right_max.append(current_max)
    right_max.reverse()

    # Calculate water trapped at each position
    return sum(
        min(left, right) - h
        for h, left, right in zip(height, left_max, right_max)
    )

def is_palindrome(array):
    n = len(array)
    for i in range(n // 2):
        if array[i] != array[n - 1 - i]:
            return False
    return True
